import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.Lq8Lraw_.js";const h=JSON.parse('{"title":"19 分支模型选型：Git Flow / GitHub Flow / Trunk-Based","description":"","frontmatter":{},"headers":[],"relativePath":"guide/collaboration/09-branching-models.md","filePath":"guide/collaboration/09-branching-models.md","lastUpdated":1792671989000}'),s={name:"guide/collaboration/09-branching-models.md"};function o(n,l,d,r,p,c){return a(),i("div",null,[...l[0]||(l[0]=[t(`<h1 id="_19-分支模型选型-git-flow-github-flow-trunk-based" tabindex="-1">19 分支模型选型：Git Flow / GitHub Flow / Trunk-Based <a class="header-anchor" href="#_19-分支模型选型-git-flow-github-flow-trunk-based" aria-label="Permalink to &quot;19 分支模型选型：Git Flow / GitHub Flow / Trunk-Based&quot;">​</a></h1><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>学完本章，你将能够：</p><ul><li>说出三种主流分支模型的结构、发布节奏与适用团队</li><li>用团队规模、发布频率、合规要求三个维度做选型</li><li>为选定的模型配置对应的分支保护规则与 CI 门禁</li><li>识别「模型没问题，但落地变形」的典型症状</li><li>从一种模型平滑迁移到另一种，而不打断交付</li></ul><h2 id="没有最好的模型-只有匹配的约束" tabindex="-1">没有最好的模型，只有匹配的约束 <a class="header-anchor" href="#没有最好的模型-只有匹配的约束" aria-label="Permalink to &quot;没有最好的模型，只有匹配的约束&quot;">​</a></h2><p>分支模型解决的是三个问题：</p><ol><li>代码从哪里进入主干？</li><li>发布版本如何冻结与修复？</li><li>多人并行时，冲突在哪里消化？</li></ol><p>约束不同，答案就不同。下面三种模型分别优化不同的目标。</p><h2 id="git-flow-为重发布节奏设计" tabindex="-1">Git Flow：为重发布节奏设计 <a class="header-anchor" href="#git-flow-为重发布节奏设计" aria-label="Permalink to &quot;Git Flow：为重发布节奏设计&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main      ──●──────────────●──────────●──      （只存已发布版本）</span></span>
<span class="line"><span>             \\            / \\        /</span></span>
<span class="line"><span>release       ●──●──●──●    ...      ...       （发布冻结、只修 bug）</span></span>
<span class="line"><span>               \\  /</span></span>
<span class="line"><span>develop   ──●───●───●───●───●───●───●──        （集成分支）</span></span>
<span class="line"><span>             \\     /</span></span>
<span class="line"><span>feature       ●───●                            （功能分支）</span></span></code></pre></div><p>核心分支：</p><ul><li><code>main</code>：永远对应生产环境，每次合并打 tag；</li><li><code>develop</code>：日常集成分支；</li><li><code>feature/*</code>：从 <code>develop</code> 切出，完成后合回；</li><li><code>release/*</code>：发布冻结，只接受 bugfix；</li><li><code>hotfix/*</code>：从 <code>main</code> 切出，修完同时合回 <code>main</code> 与 <code>develop</code>。</li></ul><p>适用：</p><ul><li>有明确版本号、需要同时维护多个已发布版本的产品（客户端、SDK、私有化部署）；</li><li>发布窗口固定，测试周期长；</li><li>团队规模中等以上，需要冻结期隔离新功能。</li></ul><p>代价：</p><ul><li>分支多、合并路径长，<code>develop</code> 长期偏离 <code>main</code>；</li><li>hotfix 要回灌两处，容易漏；</li><li>持续交付团队会觉得很重。</li></ul><h2 id="github-flow-为持续部署设计" tabindex="-1">GitHub Flow：为持续部署设计 <a class="header-anchor" href="#github-flow-为持续部署设计" aria-label="Permalink to &quot;GitHub Flow：为持续部署设计&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main     ──●────●────●────●────●──      （永远可发布）</span></span>
<span class="line"><span>            \\  /      \\  /</span></span>
<span class="line"><span>feature      ●●        ●●              （短生命周期分支 + PR）</span></span></code></pre></div><p>规则只有几条：</p><ol><li><code>main</code> 永远可部署；</li><li>任何改动都从 <code>main</code> 切分支；</li><li>通过 Pull Request 合并，必须通过 CI 与 review；</li><li>合并即部署（或手动触发部署）。</li></ol><p>适用：</p><ul><li>SaaS、Web 应用，发布成本低；</li><li>小到中型团队，review 流程顺畅；</li><li>不需要维护多个历史版本。</li></ul><p>代价：</p><ul><li>缺少发布冻结机制，合规或大版本产品需要额外补流程；</li><li>功能未完成时不能合入，否则线上暴露半成品——需要 feature flag 配合。</li></ul><h2 id="trunk-based-development-为高频集成设计" tabindex="-1">Trunk-Based Development：为高频集成设计 <a class="header-anchor" href="#trunk-based-development-为高频集成设计" aria-label="Permalink to &quot;Trunk-Based Development：为高频集成设计&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main  ──●─●─●─●─●─●─●─●──     （所有人每天多次合入）</span></span>
<span class="line"><span>         \\ /   \\ /</span></span>
<span class="line"><span>分支       ●     ●            （存活不超过 1-2 天，甚至直接提交）</span></span></code></pre></div><p>核心纪律：</p><ul><li>分支存活时间极短（通常 &lt; 1 天），或直接在主干开发；</li><li>未完成功能用 <strong>feature flag</strong> 隐藏，而不是长期挂分支；</li><li>主干必须始终绿：提交前本地跑测试，合并队列（merge queue）保证不破坏；</li><li>发布从主干切出，或直接持续部署。</li></ul><p>适用：</p><ul><li>工程能力强、CI 快（十分钟内）、测试覆盖高的团队；</li><li>需要极高发布频率（每天多次）；</li><li>微服务架构，单仓变更范围可控。</li></ul><p>代价：</p><ul><li>对测试与可观测性要求最高；</li><li>feature flag 管理不善会变成技术债；</li><li>没有强 CI 文化的团队直接照搬会频繁弄坏主干。</li></ul><h2 id="横向对比" tabindex="-1">横向对比 <a class="header-anchor" href="#横向对比" aria-label="Permalink to &quot;横向对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Git Flow</th><th>GitHub Flow</th><th>Trunk-Based</th></tr></thead><tbody><tr><td>长期分支</td><td>多（develop/release）</td><td>仅 main</td><td>仅 main</td></tr><tr><td>分支寿命</td><td>数天到数周</td><td>数小时到数天</td><td>数小时</td></tr><tr><td>发布节奏</td><td>按版本窗口</td><td>随时</td><td>每天多次</td></tr><tr><td>多版本维护</td><td>原生支持</td><td>弱</td><td>弱（靠 release 分支）</td></tr><tr><td>冲突压力</td><td>集中在合并期</td><td>分散</td><td>极低</td></tr><tr><td>CI 要求</td><td>中</td><td>中高</td><td>极高</td></tr><tr><td>新人上手成本</td><td>高</td><td>低</td><td>中</td></tr><tr><td>典型场景</td><td>客户端、SDK、私有化</td><td>SaaS、Web</td><td>大型高频团队</td></tr></tbody></table><h2 id="怎么选-三个问题" tabindex="-1">怎么选：三个问题 <a class="header-anchor" href="#怎么选-三个问题" aria-label="Permalink to &quot;怎么选：三个问题&quot;">​</a></h2><ol><li><p><strong>你需要同时维护几个已发布版本？</strong></p><ul><li>多个 → Git Flow（或 GitHub Flow + release 分支）</li><li>一个 → GitHub Flow / Trunk-Based</li></ul></li><li><p><strong>发布一次的成本有多高？</strong></p><ul><li>需要数天测试、审批、灰度 → Git Flow 的冻结期有意义</li><li>合并即可上线 → GitHub Flow</li><li>一天多次 → Trunk-Based</li></ul></li><li><p><strong>CI 能在 10 分钟内给出可信结果吗？</strong></p><ul><li>不能 → 先把 CI 建好，再谈 Trunk-Based</li><li>能，且测试覆盖高 → 可以尝试 Trunk-Based</li></ul></li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发布频率低、版本多  →  Git Flow</span></span>
<span class="line"><span>发布频率中、单版本  →  GitHub Flow</span></span>
<span class="line"><span>发布频率高、CI 强   →  Trunk-Based</span></span></code></pre></div><h2 id="分支保护-模型落地的硬约束" tabindex="-1">分支保护：模型落地的硬约束 <a class="header-anchor" href="#分支保护-模型落地的硬约束" aria-label="Permalink to &quot;分支保护：模型落地的硬约束&quot;">​</a></h2><p>无论选哪种模型，服务端规则比文档更有效。以 GitHub 为例，<code>main</code> 建议开启：</p><ul><li>Require a pull request before merging（禁止直推）</li><li>Require approvals（至少 1-2 人）</li><li>Require status checks（lint、test、build 必须绿）</li><li>Require conversation resolution（review 意见必须处理）</li><li>Require linear history（如采用 rebase 合并策略）</li><li>Restrict who can push（仅 release bot 可推）</li><li>CODEOWNERS 自动指定评审人</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Settings → Branches → Add branch protection rule</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">规则要和模型一致</p><p>Trunk-Based 却允许长期分支、GitHub Flow 却要求线性历史但团队习惯 merge、Git Flow 却没有保护 <code>release/*</code>——这些组合都会产生「制度与实操两张皮」。规则宁愿少而严，不要多而松。</p></div><h2 id="从-git-flow-迁到-github-flow-的最小路径" tabindex="-1">从 Git Flow 迁到 GitHub Flow 的最小路径 <a class="header-anchor" href="#从-git-flow-迁到-github-flow-的最小路径" aria-label="Permalink to &quot;从 Git Flow 迁到 GitHub Flow 的最小路径&quot;">​</a></h2><ol><li>停止从 <code>develop</code> 切新功能，改为从 <code>main</code> 切；</li><li>把 <code>develop</code> 剩余改动合并进 <code>main</code>，然后冻结 <code>develop</code>；</li><li>为 <code>main</code> 开启 PR + CI 保护；</li><li>引入 feature flag，替代「功能没做完不能合」的长期分支；</li><li>保留 <code>release/*</code> 仅用于需要冻结的大版本，日常发布直接从 <code>main</code> 出。</li></ol><p>不要一次性删掉所有分支，也不要同时改模型和发布流程——一次只动一个变量。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ol><li><strong>照搬大厂模型</strong>：对方有专职平台团队和秒级 CI，你没有。</li><li><strong>Git Flow 的 hotfix 忘记回灌 <code>develop</code></strong>：下次发布会把 bug 带回来。</li><li><strong>GitHub Flow 下长期挂着未完成分支</strong>：本质退化成 Git Flow，却没有冻结与集成机制。</li><li><strong>Trunk-Based 却没有 feature flag</strong>：半成品直接暴露给用户。</li><li><strong>只写文档不配保护规则</strong>：模型靠自觉执行，等于没有。</li><li><strong>同时维护两套模型</strong>：团队认知分裂，合并路径混乱。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Git Flow 优化「多版本 + 冻结发布」，GitHub Flow 优化「单主干 + 持续交付」，Trunk-Based 优化「高频集成」。</li><li>选型看三个约束：维护版本数、发布成本、CI 可信度。</li><li>模型必须配套分支保护与 CI 门禁，否则只是命名约定。</li><li>迁移一次只改一个变量，先建能力再换流程。</li><li>冲突治理的上限由分支模型决定：分支越短、集成越频繁，冲突越小越早。</li></ul>`,49)])])}const b=e(s,[["render",o]]);export{h as __pageData,b as default};
